// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type GaugeAnimationProps = Record<string, any>;

const GaugeAnimation: React.FC<GaugeAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  targetValue = 93750,
  minValue = 0,
  maxValue = 187500,
  prefix = "$",
  badgeText = "Pre-Approved Range",
  colorLow = "#ef4444",
  colorMid = "#eab308",
  colorHigh = "#22c55e",
  needleColor = "#1e293b",
  badgeColor = "#22c55e",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timing ---
  
  // 1. Arc draws in smoothly
  const arcProgress = spring({
    frame: frame - 10,
    fps,
    config: { damping: 200, stiffness: 100 },
  });

  // 2. Needle rotates and number counts up (starts slightly after arc)
  const needleProgress = spring({
    frame: frame - 25,
    fps,
    config: { damping: 14, mass: 1.2, stiffness: 120 },
  });

  // 3. Badge pops in at the end
  const badgeScale = spring({
    frame: frame - 50,
    fps,
    config: { damping: 12, stiffness: 150 },
  });
  
  const badgeOpacity = interpolate(frame - 50, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Calculations ---

  // SVG Geometry
  const radius = 400;
  const cx = 500;
  const cy = 500;
  // Arc path from left to right
  const pathData = `M ${cx - radius} ${cy} A ${radius} ${radius} 0 0 1 ${cx + radius} ${cy}`;
  // Circumference of semi-circle is Pi * r
  const pathLength = Math.PI * radius; // ~1256.6
  // Ensure the dasharray is slightly larger to prevent rendering artifacts on caps
  const dashArray = 1260; 
  const dashOffset = interpolate(arcProgress, [0, 1], [dashArray, 0]);

  // Value & Angle mapping
  const currentValue = interpolate(needleProgress, [0, 1], [minValue, targetValue]);
  
  // Calculate target angle based on value ratio
  // Range is -90deg (left) to +90deg (right)
  const valueRatio = Math.max(0, Math.min(1, (targetValue - minValue) / (maxValue - minValue)));
  const targetAngle = interpolate(valueRatio, [0, 1], [-90, 90]);
  const currentAngle = interpolate(needleProgress, [0, 1], [-90, targetAngle]);

  // Formatting the number with commas
  const formattedValue = Math.round(currentValue).toLocaleString("en-US");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Main Container */}
      <div
        style={{
          width: width * 0.8,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
        }}
      >
        {/* Gauge SVG Container */}
        <div style={{ width: "100%", position: "relative" }}>
          <svg
            viewBox="0 0 1000 550"
            style={{ width: "100%", height: "auto", display: "block" }}
          >
            <defs>
              <linearGradient id="gaugeGradient" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor={colorLow} />
                <stop offset="50%" stopColor={colorMid} />
                <stop offset="100%" stopColor={colorHigh} />
              </linearGradient>
            </defs>

            {/* The Gradient Arc */}
            <path
              d={pathData}
              fill="none"
              stroke="url(#gaugeGradient)"
              strokeWidth="80"
              strokeLinecap="round"
              strokeDasharray={dashArray}
              strokeDashoffset={dashOffset}
            />

            {/* The Needle Group */}
            {/* Origin is translated to the center point (500, 500) and then rotated */}
            <g transform={`translate(${cx}, ${cy}) rotate(${currentAngle})`}>
              {/* Needle Arm */}
              <line
                x1="0"
                y1="0"
                x2="0"
                y2={-(radius - 20)} // Extend almost to the arc
                stroke={needleColor}
                strokeWidth="16"
                strokeLinecap="round"
              />
              {/* Center Pivot Circle */}
              <circle cx="0" cy="0" r="32" fill={needleColor} />
            </g>
          </svg>
        </div>

        {/* Amount Text */}
        <div
          style={{
            marginTop: "-20px", // Pull up slightly closer to the pivot
            fontSize: "130px",
            fontWeight: 800,
            color: needleColor,
            lineHeight: 1,
            letterSpacing: "-0.03em",
          }}
        >
          {prefix}{formattedValue}
        </div>

        {/* Pill Badge */}
        <div
          style={{
            marginTop: "60px",
            backgroundColor: badgeColor,
            color: "#ffffff",
            fontSize: "40px",
            fontWeight: 600,
            padding: "24px 56px",
            borderRadius: "999px",
            boxShadow: `0 20px 40px -10px ${badgeColor}66`, // Hex shadow with alpha
            opacity: badgeOpacity,
            transform: `scale(${badgeScale})`,
          }}
        >
          {badgeText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default GaugeAnimation;